def one(task):
    dst, file_name = task
    if dst.exists() and dst.stat().st_size > 1000:
        done["skip"] += 1
        return
    for _ in range(3):
        try:
            data = _get(f"{IMAGES_BASE}/{file_name}")
            if len(data) > 1000:
                dst.write_bytes(data)
                done["ok"] += 1
                return
        except Exception:
            pass
    done["fail"] += 1
